mapper.select:
select SCENARIO_ID, SCENARIO_TYPE from TB_17_SCENARIO_MP



            SCENARIO_ID in

                #{id}



            SCENARIO_ID = #{scenarioIdList}

select t1.SCENARIO_ID as SCENARIO_SET_CODE, t1.SCENARIO_ID as SCENARIO_CODE, t1.SCENARIO_NAME, SCENARIO_TYPE, t1.TERM_DAYS, t1.CHANGE_VALUE as SCENARIO_SHIFT_VALUE, case when t1.CHANGE_TYPE='绝对变动' then'ABSOLUTE' when t1.CHANGE_TYPE='相对变动' then 'RELATIVE' else null end as SCENARIO_SHIFT_RULE, t2.RISKFACTOR_TYPE as CURVE_TYPE, t1.RISKGROUP_ID, t2.RISKFACTOR_ID as CURVE_CODE
from TB_17_SCENARIO_MP t1 left join TB_17_RISKFACTOR_MP t2 on t1.RISKGROUP_ID = t2.RISKGROUP_ID
t1.SCENARIO_ID in
#{id}
t1.SCENARIO_ID = #{scenarioIdList}

select t1.SCENARIO_ID as SCENARIO_SET_CODE, t1.SCENARIO_NAME, SCENARIO_TYPE, t1.START_DATE, t1.SAMPLES_NUMBER as SCENARIO_NO,t1.SCENARIO_NUMBER, t1.SCENARIO_DAYS as JUNP_DAY_NO,t1.INCREASE_DAYS, t1.RISKGROUP_ID, case when t1.CHANGE_TYPE='绝对变动' then'ABSOLUTE' when t1.CHANGE_TYPE='相对变动' then 'RELATIVE' else null end as SCENARIO_SHIFT_RULE, t2.RISKFACTOR_TYPE from TB_17_SCENARIO_MP t1 left join TB_17_RISKFACTOR_MP t2 on t1.RISKGROUP_ID = t2.RISKGROUP_ID
t1.SCENARIO_ID in
#{id}
t1.SCENARIO_ID = #{scenarioIdList}

select t1.SCENARIO_ID as SCENARIO_SET_CODE, t1.SCENARIO_NAME, SCENARIO_TYPE, t1.START_DATE, t1.SCENARIO_NUMBER as SCENARIO_NO, t1.SCENARIO_DAYS as JUNP_DAY_NO,t1.INCREASE_DAYS, t1.RISKGROUP_ID, case when t1.CHANGE_TYPE='绝对变动' then'ABSOLUTE' when t1.CHANGE_TYPE='相对变动' then 'RELATIVE' else null end as SCENARIO_SHIFT_RULE, t2.RISKFACTOR_TYPE from TB_17_SCENARIO_MP t1 left join TB_17_RISKFACTOR_MP t2 on t1.RISKGROUP_ID = t2.RISKGROUP_ID
t1.SCENARIO_ID in
#{id}
t1.SCENARIO_ID = #{scenarioIdList}

select 'IR_SPOT' as CURVE_TYPE, CURVE_CODE, DATA_DATE, TERM_CODE, TERM_DAYS, RATE as YIELD_RATE from TB_19_IR_CURVE_BOOTSTRAP



            AND DATA_DATE BETWEEN #{startDate} AND #{endDate}


            AND DATA_DATE = #{startDate}


            AND DATA_DATE = #{endDate}


    and BINARY CURVE_CODE in (
        select t2.RISKFACTOR_ID as CURVE_CODE
        from TB_17_SCENARIO_MP t1
        left join
        TB_17_RISKFACTOR_MP t2
        on t1.RISKGROUP_ID = t2.RISKGROUP_ID
        where t1.SCENARIO_ID = #{scenarioId}
        and t2.RISKFACTOR_TYPE = 'IR_SPOT'
    )

select 'FX_SPOT' as CURVE_TYPE, CURVE_CODE, DATA_DATE, null as TERM_CODE, null as TERM_DAYS, EXCHANGE_RATE as YIELD_RATE from V_MRM_SPOT_RATE



            AND DATA_DATE BETWEEN #{startDate} AND #{endDate}


            AND DATA_DATE = #{startDate}


            AND DATA_DATE = #{endDate}


    and BINARY CURVE_CODE in (
    select t2.RISKFACTOR_ID as CURVE_CODE
    from TB_17_SCENARIO_MP t1
    left join
    TB_17_RISKFACTOR_MP t2
    on t1.RISKGROUP_ID = t2.RISKGROUP_ID
    where t1.SCENARIO_ID = #{scenarioId}
    and t2.RISKFACTOR_TYPE = 'FX_SPOT'
    )

select 'COMM_SPOT' as CURVE_TYPE, CURVE_CODE, DATA_DATE, TERM_CODE, TERM_DAYS, COMM_PRICE as YIELD_RATE from TB_19_COMM_CURVE



            AND DATA_DATE BETWEEN #{startDate} AND #{endDate}


            AND DATA_DATE = #{startDate}


            AND DATA_DATE = #{endDate}


    and BINARY CURVE_CODE in (
    select t2.RISKFACTOR_ID as CURVE_CODE
    from TB_17_SCENARIO_MP t1
    left join
    TB_17_RISKFACTOR_MP t2
    on t1.RISKGROUP_ID = t2.RISKGROUP_ID
    where t1.SCENARIO_ID = #{scenarioId}
    and t2.RISKFACTOR_TYPE = 'COMM_SPOT'
    )

select 'FX_VOL' as CURVE_TYPE, CURVE_CODE, DATA_DATE, TERM_CODE, TERM_DAYS, DELTA, BFRR_TYPE, VOLATILITY_RATE as YIELD_RATE from TB_19_FX_VOL



            AND DATA_DATE BETWEEN #{startDate} AND #{endDate}


            AND DATA_DATE = #{startDate}


            AND DATA_DATE = #{endDate}


    and BINARY CURVE_CODE in (
    select t2.RISKFACTOR_ID as CURVE_CODE
    from TB_17_SCENARIO_MP t1
    left join
    TB_17_RISKFACTOR_MP t2
    on t1.RISKGROUP_ID = t2.RISKGROUP_ID
    where t1.SCENARIO_ID = #{scenarioId}
    and t2.RISKFACTOR_TYPE = 'FX_VOL'
    )

select 'IR_VOL' as CURVE_TYPE, CURVE_CODE, DATA_DATE, TERM_CODE, TERM_DAYS, UND_TERM_CODE AS DELTA, VOLATILITY_RATE as YIELD_RATE from TB_19_IR_VOL



            AND DATA_DATE BETWEEN #{startDate} AND #{endDate}


            AND DATA_DATE = #{startDate}


            AND DATA_DATE = #{endDate}


    and BINARY CURVE_CODE in (
    select t2.RISKFACTOR_ID as CURVE_CODE
    from TB_17_SCENARIO_MP t1
    left join
    TB_17_RISKFACTOR_MP t2
    on t1.RISKGROUP_ID = t2.RISKGROUP_ID
    where t1.SCENARIO_ID = #{scenarioId}
    and t2.RISKFACTOR_TYPE = 'IR_VOL'
    )


select 'COMM_VOL' as CURVE_TYPE, CURVE_CODE, DATA_DATE, TERM_CODE, TERM_DAYS, DELTA, 'BFRR_TYPE' AS BFRR_TYPE, VOLATILITY_RATE as YIELD_RATE from TB_19_COMM_VOL



            AND DATA_DATE BETWEEN #{startDate} AND #{endDate}


            AND DATA_DATE = #{startDate}


            AND DATA_DATE = #{endDate}


    and BINARY CURVE_CODE in (
    select t2.RISKFACTOR_ID as CURVE_CODE
    from TB_17_SCENARIO_MP t1
    left join
    TB_17_RISKFACTOR_MP t2
    on t1.RISKGROUP_ID = t2.RISKGROUP_ID
    where t1.SCENARIO_ID = #{scenarioId}
    and t2.RISKFACTOR_TYPE = 'COMM_VOL'
    )

select CALENDAR as CALENDAR_CODE, HOL_DATE as DATA_DATE
from TB_17_CALENDAR
where CALENDAR = #{calPEK}

